/* cache the id's that meet the criteria into a temporary table */ SELECT SessionID INTO #ExpiredSessions FROM AC_ProgramSpecificSessionState as s WHERE ProgramSpecificId = AND LastUpdateDate <=
DELETE FROM AC_Session WHERE SessionID IN (SELECT SessionID FROM #ExpiredSessions) DELETE FROM AC_SessionState WHERE SessionID IN (SELECT SessionID FROM #ExpiredSessions) DELETE FROM AC_ProgramSpecificSessionState WHERE SessionID IN (SELECT SessionID FROM #ExpiredSessions)
